package ledger

import "errors"

// ErrInsufficient reports a withdrawal larger than the balance.
var ErrInsufficient = errors.New("insufficient funds")

// Ledger tracks a single account balance in cents.
type Ledger struct {
	balance int
}

// Deposit adds cents to the balance.
func (l *Ledger) Deposit(cents int) {
	l.balance += cents
}

// Withdraw removes cents from the balance when enough is available.
func (l *Ledger) Withdraw(cents int) error {
	if cents > l.balance {
		return ErrInsufficient
	}
	l.balance -= cents
	return nil
}

// Balance answers the current balance in cents.
func (l *Ledger) Balance() int {
	return l.balance
}

