package ledger

import "testing"

func TestWithdrawBelowBalanceSucceeds(t *testing.T) {
	var ledger Ledger
	ledger.Deposit(1000)
	if err := ledger.Withdraw(400); err != nil {
		t.Fatalf("Withdraw: %v", err)
	}
	if got := ledger.Balance(); got != 600 {
		t.Fatalf("Balance = %d, want 600", got)
	}
}

func TestWithdrawAboveBalanceIsRejected(t *testing.T) {
	var ledger Ledger
	ledger.Deposit(100)
	if err := ledger.Withdraw(200); err != ErrInsufficient {
		t.Fatalf("err = %v, want ErrInsufficient", err)
	}
}
